// 1) Repo inventory
const tree = await tools.bash({command: "find . -type f -not -path '*/node_modules/*' -not -path '*/.git/*' | sort", timeout: 15});
console.log("=== FILES ===\n" + tree.output);

// 2) All legacyLog( occurrences
const grepCalls = await tools.bash({command: "grep -rn 'legacyLog(' --exclude-dir=node_modules --exclude-dir=.git . 2>/dev/null; true", timeout: 15});
console.log("=== legacyLog( OCCURRENCES ===\n" + grepCalls.output);

// 3) Config files content
const cfgList = await tools.bash({command: "ls config/*.json 2>/dev/null; true", timeout: 10});
const cfgFiles = cfgList.output.trim().split("\n").filter(Boolean);
const cfgContents = {};
for (const f of cfgFiles) {
  const r = await tools.bash({command: "cat " + f, timeout: 10});
  cfgContents[f] = r.output;
  console.log("=== CONFIG " + f + " ===\n" + r.output);
}

// 4) Load every JS source (for enclosing-function analysis and config key usage)
const jsList = await tools.bash({command: "find . -name '*.js' -not -path '*/node_modules/*' -not -path '*/.git/*' | sort", timeout: 10});
const jsFiles = jsList.output.trim().split("\n").filter(Boolean);
console.log("=== JS FILES ===\n" + jsFiles.join("\n"));
const contents = {};
await Promise.allSettled(jsFiles.map(async f => {
  const r = await tools.bash({command: "cat " + f, timeout: 10});
  contents[f.replace(/^\.\//, "")] = r.output;
}));

// 5) Enclosing-function analysis for each call site
const KEYWORDS = new Set(["if","for","while","switch","catch","function","return","else","do","new","typeof","await"]);
function findEnclosing(lines, idx) {
  for (let i = idx - 1; i >= 0; i--) {
    const L = lines[i];
    let m;
    if ((m = L.match(/function\s+([A-Za-z_$][\w$]*)\s*\(/))) return m[1];
    if ((m = L.match(/([A-Za-z_$][\w$]*)\s*[:=]\s*(?:async\s*)?(?:function\b|\([^)]*\)\s*=>|[A-Za-z_$][\w$]*\s*=>)/))) {
      if (!KEYWORDS.has(m[1])) return m[1];
    }
    if ((m = L.match(/^\s*(?:static\s+|async\s+|get\s+|set\s+)*([A-Za-z_$][\w$]*)\s*\([^)]*\)\s*\{/))) {
      if (!KEYWORDS.has(m[1])) return m[1] + " (method-style)";
    }
  }
  return "<top-level>";
}

const callers = [];
let total = 0;
for (const f of Object.keys(contents)) {
  const lines = contents[f].split("\n");
  lines.forEach((L, i) => {
    if (!L.includes("legacyLog(")) return;
    // skip the definition itself
    if (/function\s+legacyLog\s*\(/.test(L) || /legacyLog\s*[:=]/.test(L)) return;
    const count = (L.match(/legacyLog\(/g) || []).length;
    total += count;
    const fn = findEnclosing(lines, i);
    callers.push({ file: f, fn, line: i + 1, text: L.trim() });
  });
}
console.log("=== CALL SITES ===");
callers.forEach(c => console.log(`${c.file}:${c.fn} (line ${c.line}): ${c.text}`));
console.log("TOTAL CALL SITES: " + total);

// 6) Config key usage: check every key against all JS sources (excluding config dir)
const srcText = jsFiles
  .filter(f => !f.replace(/^\.\//, "").startsWith("config/"))
  .map(f => contents[f.replace(/^\.\//, "")]).join("\n");
const keys = [];
for (const f of Object.keys(cfgContents)) {
  try {
    const flat = (obj, prefix) => {
      for (const k of Object.keys(obj)) {
        keys.push({ file: f, key: k, path: prefix ? prefix + "." + k : k });
        if (obj[k] && typeof obj[k] === "object" && !Array.isArray(obj[k])) flat(obj[k], prefix ? prefix + "." + k : k);
      }
    };
    flat(JSON.parse(cfgContents[f]), "");
  } catch (e) { console.log("config parse error " + f + ": " + e.message); }
}
console.log("=== KEY USAGE ===");
for (const k of keys) {
  const used = new RegExp('["\'`]' + k.key.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + '["\'`.]').test(srcText)
    || srcText.includes("." + k.key) || srcText.includes(k.key + ":") || srcText.includes(k.key + ",");
  console.log(`${k.file} :: ${k.path} -> ${used ? "USED" : "NOT FOUND"}`);
}
return "done";

const files = ["src/auth/tokens.js","src/auth/session.js","src/jobs/cleanup.js","src/jobs/report.js","src/util/retry.js","src/api/users.js","src/api/orders.js","src/util/legacyLogger.js"];
const out = await Promise.all(files.map(async f => {
  const r = await tools.bash({command: "cat " + f, timeout: 10});
  return "=== " + f + " ===\n" + r.output;
}));
console.log(out.join("\n\n"));
const arch = await tools.bash({command: "grep -rn 'archiveAfterDays' . --exclude-dir=node_modules --exclude-dir=.git 2>/dev/null; true", timeout: 10});
console.log("=== archiveAfterDays anywhere ===\n" + (arch.output || "(no matches outside config/jobs.json itself)"));
const cfgload = await tools.bash({command: "cat src/lib/config.js", timeout: 10});
console.log("=== src/lib/config.js ===\n" + cfgload.output);
return "ok";
